<?php
namespace App\Http\Requests\Accounts;
use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;use Illuminate\Validation\Validator;
class VoucherRequest extends FormRequest{public function authorize():bool{return $this->user()?->can('accounts.create')??false;}public function rules():array{return['type'=>['required',Rule::in(['journal','contra','expense','income','opening'])],'voucher_date'=>['required','date'],'reference_number'=>['nullable','string','max:100'],'narration'=>['nullable','string','max:2000'],'lines'=>['required','array','min:2'],'lines.*.ledger_account_id'=>['required','exists:ledger_accounts,id'],'lines.*.party_id'=>['nullable','exists:parties,id'],'lines.*.debit'=>['nullable','numeric','min:0'],'lines.*.credit'=>['nullable','numeric','min:0'],'lines.*.description'=>['nullable','string','max:255']];}public function after():array{return[function(Validator $v){$d=collect($this->input('lines'))->sum(fn($x)=>(float)($x['debit']??0));$c=collect($this->input('lines'))->sum(fn($x)=>(float)($x['credit']??0));if($d<=0||abs($d-$c)>0.009)$v->errors()->add('lines','Voucher debit and credit totals must be equal and greater than zero.');}];}}
